118		public static void Init()
119		{
120			frame = 0f;
121			if (creditLine == null)
122			{
123				InitData();
124			}
125			GameStateManager.gameState = 4;
126			maxScroll = -1f;
127			outFrame = 0f;
128			Player mainPlayer = PlayerMgr.GetMainPlayer();
129			mainPlayer.respawnLoc = new Vector2(900f, 14800f);
130			mainPlayer.respawnLoc.Y = CharCols.GetGround(mainPlayer.respawnLoc);
131			mainPlayer.sanctuaryRespawnLoc = mainPlayer.respawnLoc;
132			Character playerCharacter = CharMgr.GetPlayerCharacter(mainPlayer);
133			if (mainPlayer.playthroughNumber < 7)
134			{
135				mainPlayer.playthroughNumber++;
136			}
137			List<string> list = new List<string>();
138			foreach (string flag in mainPlayer.flags)
139			{
140				if (flag.StartsWith("#wi#_"))
141				{
142					list.Add(flag);
143				}
144			}
145			mainPlayer.flags.Clear();
146			foreach (string item in list)
147			{
148				mainPlayer.flags.Add(item);
149			}
150			mainPlayer.challenge.SetChallengeFlags();
151			for (int i = 0; i < mainPlayer.playerInv.inventory.Length; i++)
152			{
153				if (mainPlayer.playerInv.inventory[i] != null)
154				{
155					InvLoot invLoot = mainPlayer.playerInv.inventory[i];
156					LootDef lootDef = LootCatalog.category[invLoot.category].loot[invLoot.catalogIdx];
157					if (lootDef.category == 3 && lootDef.type == 2)
158					{
159						mainPlayer.playerInv.inventory[i] = null;
160					}
161				}
162			}
163			mainPlayer.flags.Add("chose_creed");
164			mainPlayer.playerInv.RemoveKeys();
165			mainPlayer.ResetSanctuaries();
166			MapMgr.sanctuaryMgr.InitFromMap();
167			MapMgr.sanctuaryMgr.InitToPlayer(mainPlayer);
168			mainPlayer.WriteCharSave(playerCharacter);
169		}
