171		public static void Draw(GraphicsDevice GraphicsDevice)
172		{
173			float hdFactor = ScrollManager.GetHdFactor();
174			GraphicsDevice.Clear(new Color(0f, 0f, 0f, 1f));
175			SpriteTools.BeginAdditive();
176			float num = (frame - 3f) * 100f;
177			if (num < 0f)
178			{
179				num = 0f;
180			}
181			if (maxScroll > -1f && num > maxScroll)
182			{
183				num = maxScroll;
184			}
185			float num2 = 48f * hdFactor;
186			for (int i = 0; i < creditLine.Length; i++)
187			{
188				if (creditLine[i].name == null)
189				{
190					continue;
191				}
192				float num3 = num;
193				if (i > creditLine.Length - 3 && maxScroll > -1f && num3 > maxScroll)
194				{
195					num3 = maxScroll;
196				}
197				Vector2 loc = new Vector2(ScrollManager.screenSize.X / 2f, (float)i * num2 - num3 * hdFactor + ScrollManager.screenSize.Y / 2f);
198				if (loc.Y > 100f * hdFactor && loc.Y < ScrollManager.screenSize.Y - 100f * hdFactor)
199				{
200					float num4 = 1f;
201					if (loc.Y < 200f * hdFactor)
202					{
203						num4 = (loc.Y - 100f * hdFactor) / (100f * hdFactor);
204					}
205					if (loc.Y > ScrollManager.screenSize.Y - 200f * hdFactor)
206					{
207						num4 = (ScrollManager.screenSize.Y - 100f * hdFactor - loc.Y) / (100f * hdFactor);
208					}
209					if (outFrame > 3f)
210					{
211						num4 *= (6f - outFrame) / 3f;
212						if (num4 < 0f)
213						{
214							num4 = 0f;
215						}
216					}
217					Color color = new Color(1f, 1f, 1f, num4);
218					switch (creditLine[i].type)
219					{
220					case 2:
221						color = new Color(1f, 1f, 0.7f, num4);
222						break;
223					case 1:
224						color = new Color(0.7f, 0.7f, 0.7f, num4);
225						break;
226					}
227					Text.DrawText(creditLine[i].name, loc, color, 0.55f * hdFactor, 1);
228				}
229				if (i == creditLine.Length - 1 && loc.Y < ScrollManager.screenSize.Y / 2f)
230				{
231					maxScroll = num;
232				}
233			}
234			if (frame < 1f)
235			{
236				SpriteTools.sprite.Draw(Game1.nullTex, new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y), new Color(1f, 1f, 1f, 1f - frame));
237			}
238			if (outFrame > 3f)
239			{
240				SpriteTools.sprite.Draw(Game1.nullTex, new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y), new Color(1f, 1f, 1f, (outFrame - 3f) / 3f));
241			}
242			SpriteTools.End();
243		}
244	}
