  6	public class GameConsole
  7	{
  8		private static object consoleSemaphore;
  9	
 10		private static bool inited;
 11	
 12		public static void Init()
 13		{
 14			consoleSemaphore = new object();
 15			inited = true;
 16		}
 17	
 18		public static void WriteLine(string s)
 19		{
 20			if (!inited)
 21			{
 22				Init();
 23			}
 24			if (Monitor.TryEnter(consoleSemaphore, 1000))
 25			{
 26				try
 27				{
 28					Console.WriteLine(s);
 29				}
 30				finally
 31				{
 32					Monitor.Exit(consoleSemaphore);
 33				}
 34			}
 35		}
 36	}
