 79	
 80		internal static void Init(GraphicsDevice dev, ContentManager Content)
 81		{
 82			GraphicsDevice = dev;
 83			logoTex = Content.Load<Texture2D>("gfx/skalogo");
 84			logoblurTex = Content.Load<Texture2D>("gfx/skalogoblur");
 85			circlesTex = Content.Load<Texture2D>("gfx/circles");
 86			trrTex = Content.Load<Texture2D>("gfx/trrlogo");
 87		}
