 89		internal static void Update()
 90		{
 91			frame += Game1.frameTime;
 92			float num = 3f;
 93			switch (loadScreen)
 94			{
 95			case 0:
 96				num = 5f;
 97				break;
 98			case 1:
 99				num = 5f;
100				break;
101			case 2:
102				num = 5f;
103				break;
104			}
105			if (loadScreen >= 2)
106			{
107				num = ((!loaded || !(frame > num - 1f)) ? (-1f) : 0f);
108			}
109			if (num > -1f && frame > num - 1f)
110			{
111				outFrame += Game1.frameTime;
112			}
113			if (outFrame < 0.8f && ((frame > 0.5f && frame < num - 1f) || (frame > 0.5f && loadScreen == 2 && loaded)))
114			{
115				GamePadState state = GamePad.GetState(PlayerIndex.One);
116				KeyboardState state2 = Keyboard.GetState(PlayerIndex.One);
117				MouseState state3 = Mouse.GetState();
118				if (state.Buttons.A == ButtonState.Pressed || state2.IsKeyDown(Keys.Space) || state3.LeftButton == ButtonState.Pressed)
119				{
120					outFrame = 1f;
121				}
122			}
123			if (outFrame >= 1f)
124			{
125				frame = 0f;
126				outFrame = 0f;
127				loadScreen++;
128				if (loadScreen >= 3)
129				{
130					GameStateManager.gameState = 2;
131				}
132			}
133		}
134	
135		internal static void Draw()
136		{
137			GraphicsDevice.Clear(new Color(0f, 0f, 0f, 1f));
138			float num = 1f;
139			if (frame < 1f)
140			{
141				num = frame;
142			}
143			if (outFrame > 0f)
144			{
145				num -= outFrame;
146			}
147			if (num < 0f)
148			{
149				return;
150			}
151			float hdFactor = ScrollManager.GetHdFactor();
152			switch (loadScreen)
153			{
154			case 2:
155				if (DialogMgr.locStringsLoaded)
156				{
157					if (saveWarnStr == null)
158					{
159						saveWarnStr = WordWrap.Wrap(null, LocStrings.GetLocStr(335) + "\r\n\r\n" + LocStrings.GetLocStr(1038), 50, 0);
160					}
161					if (Text.loaded)
162					{
163						SpriteTools.BeginAlpha();
164						for (int i = 0; i < saveWarnStr.Length; i++)
165						{
166							Text.DrawText(saveWarnStr[i], ScrollManager.screenSize / 2f + new Vector2(0f, ((float)saveWarnStr.Length * -32f - 50f + (float)i * 32f) * hdFactor), new Color(1f, 1f, 1f, num), 0.65f * hdFactor, 1);
167						}
168						SpriteTools.End();
169					}
170				}
171				if (InterfaceRender.loaded)
172				{
173					HUD.DrawSaving(frame, ScrollManager.screenSize / 2f, num);
174				}
175				break;
176			case 1:
177				SpriteTools.BeginAlpha();
178				SpriteTools.sprite.Draw(trrTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, trrTex.Width, trrTex.Height), new Color(1f, 1f, 1f, num), 0f, new Vector2(trrTex.Width, trrTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
179				SpriteTools.End();
180				break;
181			case 0:
182				SpriteTools.BeginAdditive();
183				SpriteTools.sprite.Draw(logoTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, logoTex.Width, logoTex.Height), new Color(1f, 1f, 1f, num * 0.45f * Rand.GetRandomFloat(0.9f, 1f)), 0f, new Vector2(logoTex.Width, logoTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
184				SpriteTools.sprite.Draw(logoblurTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, logoblurTex.Width, logoblurTex.Height), new Color(1f, 1f, 1f, num * ((float)Math.Sin(frame * 1.5f) * 0.25f + 0.75f) * Rand.GetRandomFloat(0.9f, 1f)), 0f, new Vector2(logoblurTex.Width, logoblurTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
185				SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.35f * Rand.GetRandomFloat(0.9f, 1f)), frame * -0.7f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 0.75f * hdFactor, SpriteEffects.None, 0f);
186				SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.35f * Rand.GetRandomFloat(0.9f, 1f)), frame * 0.6f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 1f * hdFactor, SpriteEffects.None, 0f);
187				SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.5f * Rand.GetRandomFloat(0.9f, 1f)), frame * -0.25f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 1.35f * hdFactor, SpriteEffects.None, 0f);
188				SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.2f * Rand.GetRandomFloat(0.9f, 1f)), frame * 0.2f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 2f * hdFactor, SpriteEffects.None, 0f);
189				SpriteTools.sprite.Draw(circlesTex, ScrollManager.screenSize / 2f, new Rectangle(0, 0, circlesTex.Width, circlesTex.Height), new Color(1f, 1f, 1f, num * 0.1f * Rand.GetRandomFloat(0.9f, 1f)), frame * -0.1f, new Vector2(circlesTex.Width, circlesTex.Height) / 2f, 2.5f * hdFactor, SpriteEffects.None, 0f);
190				SpriteTools.End();
191				break;
192			}
193		}
194	}

