152		public static float GetAlphaVal(float drawFrame, float thresh, float ramp)
153		{
154			if (drawFrame < 0f)
155			{
156				return 0f;
157			}
158			if (drawFrame > 5f)
159			{
160				return 6f - drawFrame;
161			}
162			if (drawFrame < thresh - ramp)
163			{
164				return 0f;
165			}
166			if (drawFrame < thresh)
167			{
168				return (drawFrame - (thresh - ramp)) / ramp + Rand.GetRandomFloat(0f, 0.01f);
169			}
170			return 1f;
171		}
