		if (t.Contains("[n]"))
		{
			t = (text = text.Replace("[n]", p.name));
		}
		if (t.Contains("[g?"))
		{
			while (text.Contains("[g?"))
			{
				for (int i = 0; i < text.Length - 2; i++)
				{
					if (!(text.Substring(i, 3) == "[g?"))
					{
						continue;
					}
					int num = -1;
					for (int j = i; j < text.Length; j++)
					{
						if (text.Substring(j, 1) == "]")
						{
							num = j;
							break;
						}
					}
					if (num != -1)
					{
						string text2 = text.Substring(i, num - i + 1);
						string[] array = text2.Substring(3, text2.Length - 4).Split(new string[1] { ":" }, StringSplitOptions.None);
						if (array.Length > 1)
						{
							_ = p?.skinClass;
							text = text.Replace(text2, (p.skinClass == 0) ? array[0] : array[1]);
						}
						else
						{
							text = text.Replace("[g?", "#ERR#");
						}
					}
					else
					{
						text = text.Replace("[g?", "#ERR#");
					}
				}
			}
