	public static int BreakLine(string text, int pos, int max)
	{
		int num = max - 1;
		while (num >= 0 && !char.IsWhiteSpace(text[pos + num]) && text[pos + num] < '⻠')
		{
			num--;
		}
		if (num < 0)
		{
			return max;
		}
		while (num >= 0 && char.IsWhiteSpace(text[pos + num]))
		{
			num--;
		}
		return num + 1;
	}
