252		public void Update()
253		{
254			if (Text.arrowHighlight > 0f)
255			{
256				Text.arrowHighlight -= Game1.realTime;
257				if (Text.arrowHighlight < 0f)
258				{
259					Text.arrowHighlight = 0f;
260				}
261			}
262			if (Text.arrowHighlight < 0f)
263			{
264				Text.arrowHighlight += Game1.realTime;
265				if (Text.arrowHighlight > 0f)
266				{
267					Text.arrowHighlight = 0f;
268				}
269			}
270			if (GuideStuff.keyboardActive)
271			{
272				GuideStuff.keyboardFrame += Game1.frameTime;
273				if (GuideStuff.keyboardFrame > (float)Math.PI * 2f)
274				{
275					GuideStuff.keyboardFrame -= (float)Math.PI * 2f;
276				}
277			}
278			switch (transMode)
279			{
280			case 1:
281				transFrame += Game1.frameTime;
282				if (menuLevel[curLev].showParent == transLevel || (menuLevel[transLevel].showParent > -1 && menuLevel[transLevel].showParent == menuLevel[curLev].showParent))
283				{
284					transFrame += Game1.frameTime * 3f;
285				}
286				if (GameStateManager.gameState == 1)
287				{
288					transFrame += Game1.frameTime * 3f;
289				}
290				if (!(transFrame > 1f))
291				{
292					break;
293				}
294				if (menuLevel[curLev].showParent == transLevel)
295				{
296					curLev = transLevel;
297					transMode = 0;
298					transFrame = 0f;
299					break;
300				}
301				if (GameStateManager.gameState == 2)
302				{
303					if (transLevel == 3)
304					{
305						GameStateManager.gameState = 0;
306					}
307				}
308				else if (GameStateManager.gameState == 0 && transLevel == 1)
309				{
310					GameStateManager.gameState = 2;
311					LogoRender.drawFrame = -1f;
312					LogoRender.drawAlpha = 0f;
313				}
314				curLev = transLevel;
315				transFrame = 0f;
316				transMode = 2;
317				menuLevel[curLev].scroll = 0f;
318				break;
319			case 3:
320				transFrame += Game1.frameTime;
321				if (transFrame > 1f)
322				{
323					curLev = transLevel;
324					transFrame = 0f;
325					transMode = 4;
326					switch (transSpecial)
327					{
328					case 0:
329						NewGameManager.NewGame(p);
330						break;
331					case 1:
332						NewGameManager.LoadGame(p, GameStateManager.GetMainPlayer().dataIdx);
333						break;
334					}
335				}
336				break;
337			case 2:
338			case 4:
339				if (GameStateManager.gameState == 2 || GameStateManager.gameState == 0)
340				{
341					menuLevel[curLev].selected = 0;
342					menuLevel[curLev].scroll = (menuLevel[curLev].selectedScroll = 100f);
343					for (int i = 0; i < menuLevel[curLev].item.Length; i++)
344					{
345						if (i == 0)
346						{
347							menuLevel[curLev].item[i].sel = 1f;
348						}
349						else
350						{
351							menuLevel[curLev].item[i].sel = 0f;
352						}
353					}
354				}
355				if (transMode == 2 && GameStateManager.gameState == 2)
356				{
357					if (LogoRender.drawFrame > 3f)
358					{
359						transFrame += Game1.frameTime;
360					}
361				}
362				else
363				{
364					transFrame += Game1.frameTime;
365				}
366				if (GameStateManager.gameState == 1)
367				{
368					transFrame += Game1.frameTime * 3f;
369					if (menuLevel[curLev].optionScroll)
370					{
371						menuLevel[curLev].scroll = (menuLevel[curLev].selectedScroll = 520f * ScrollManager.GetHdFactor());
372						menuLevel[curLev].selected = 0;
373					}
374				}
375				if (transMode == 2 && menuLevel[curLev].showParent > -1)
376				{
377					transFrame += Game1.frameTime * 3f;
378				}
379				if (transFrame > 1f)
380				{
381					transMode = 0;
382				}
383				break;
384			}
385			for (int j = 0; j < menuLevel.Length; j++)
386			{
387				menuLevel[j].Update(p, j);
388			}
389		}
