public static void DrawScore(int s, Vector2 loc, Color color, float size, int align)
{
	float num = 1f;
	size *= 0.8f * num;
	if (align != 2)
	{
		for (int num2 = s; num2 > 0; num2 /= 10)
		{
			char c = (char)(num2 % 10 + 48);
			loc.X += GetLength(c) * size * ((align == 0) ? 1f : 0.5f);
		}
	}
	if (s == 0)
	{
		char c2 = (char)(s % 10 + 48);
		Rectangle value = new Rectangle((c2 - 32) % 8 * 64, (c2 - 32) / 8 * 64, 60, 64);
		if (align == 2)
		{
			loc.X -= GetLength(c2) * size;
		}
		SpriteTools.sprite.Draw(texture, loc, value, color, 0f, new Vector2(0f, 32f), size, SpriteEffects.None, 1f);
	}
	else
	{
		while (s > 0)
		{
			char c3 = (char)(s % 10 + 48);
			Rectangle value2 = new Rectangle((c3 - 32) % 8 * 64, (c3 - 32) / 8 * 64, 60, 64);
			loc.X -= GetLength(c3) * size;
			SpriteTools.sprite.Draw(texture, loc, value2, color, 0f, new Vector2(0f, 32f), size, SpriteEffects.None, 1f);
			s /= 10;
		}
	}
}

public static void DrawPercentage(float f, Vector2 loc, Color color, float size, int align)
{
	f *= 100f;
	float num = 1f;
	size *= 0.8f * num;
	int num2 = (int)f;
	int c = (int)(f * 10f) % 10;
	loc = DrawCharacter('%', loc, color, size, 2);
	loc = DrawCharacter(c, loc, color, size, 2);
	loc = DrawCharacter('.', loc, color, size, 2);
	if (num2 == 0)
	{
		loc = DrawCharacter(0, loc, color, size, 2);
		return;
	}
	while (num2 > 0)
	{
		loc = DrawCharacter(num2 % 10, loc, color, size, 2);
		num2 /= 10;
	}
}

public static void DrawScore(float f, Vector2 loc, Color color, float size, int align)
{
	size *= 0.8f;
	bool flag = f < 0f;
	if (flag)
	{
		f = 0f - f;
	}
	int num = (int)f;
	loc = DrawCharacter((int)(f * 10f) % 10, loc, color, size, 2);
	loc = DrawCharacter('.', loc, color, size, 2);
	if (num == 0)
	{
		loc = DrawCharacter(0, loc, color, size, 2);
	}
	else
	{
		while (num > 0)
		{
			loc = DrawCharacter(num % 10, loc, color, size, 2);
			num /= 10;
		}
	}
	if (flag)
	{
		loc = DrawCharacter('-', loc, color, size, 2);
	}
}

